mapper.sql:
FROM mission m
JOIN mission_version v ON v.id = m.current_version_id

    m.status = #{filter.status}
    AND #{filter.grade} BETWEEN v.grade_min AND v.grade_max
    AND v.thinking_type = #{filter.thinkingType}

mapper.select:
SELECT m.id 
ORDER BY m.sort_order, m.id
LIMIT #{filter.size} OFFSET #{offset}

mapper.update:
UPDATE mission
SET status = 'PUBLISHED', published_version_id = current_version_id,
    published_rubric_version_id = current_rubric_version_id, published_at = #{now}, updated_at = #{now}
WHERE id = #{missionId}

mapper.insert:
INSERT INTO mission_review (id, mission_id, mission_version_id, rubric_version_id, reviewer_id, result, comment, created_at)
SELECT #{id}, m.id, m.current_version_id, m.current_rubric_version_id, #{reviewerId}, #{result},
       #{comment,jdbcType=VARCHAR}, #{now}
FROM mission m WHERE m.id = #{missionId}
